"   const handleOldKOTCancel = () => {
    const selectedIndices = Object.keys(selectedOldKOTItems).filter(idx => selectedOldKOTItems[idx]);
    if (selectedIndices.length === 0) return toast.warning("No items selected!");

    const missingReason = selectedIndices.some(idx => !oldKOTItemReasons[idx]?.trim());
    if (missingReason) return toast.warning("Please provide a reason for all cancelled items!");

    const currentBill = tableBills[selectedTable.id] || [];
    const cancelledItems = currentBill.filter((_, idx) => selectedOldKOTItems[idx]);

    const updatedBill = currentBill.map((item, idx) => {
      if (selectedOldKOTItems[idx]) {
        return { ...item, isCancelled: true, cancelReason: oldKOTItemReasons[idx] };
      }
      return item;
    });

    setTableBills(prev => ({ ...prev, [selectedTable.id]: updatedBill }));

    const activeItems = updatedBill.filter(item => !item.isCancelled);
    if (activeItems.length === 0) {
      setTableStatuses(statusPrev => ({ ...statusPrev, [selectedTable.id]: 'AVAILABLE' }));
      setTableActiveTimestamps(timePrev => { const n = { ...timePrev }; delete n[selectedTable.id]; return n; });
      setTableBillNumbers(numPrev => { const n = { ...numPrev }; delete n[selectedTable.id]; return n; });
      releaseTableExtraState(selectedTable.id);
      if (selectedTable.is_temporary) {
        setTables(prev => prev.filter(t => t.id !== selectedTable.id));
      }
      setIsOldKOTModalOpen(false);
      setSelectedTable(null);
    }

    if (printCancelledKOT) {
      const bNo = tableBillNumbers[selectedTable.id];
      handlePrintKOT(cancelledItems, selectedTable.table_name, bNo, 'CANCELLED');
    }

    setSelectedOldKOTItems({});
    setOldKOTItemReasons({});
    setSelectAllOldKOT(false);
    toast.success("Selected items cancelled successfully.");
  };"

